def on_bar(ctx):
    closes = ctx.history("close", 20)
    if len(closes) < 20:
        return None
    ma20 = sum(closes) / len(closes)
    if not ctx.has_position and ctx.close > ma20:
        return buy(pct_of_cash=0.5)
    if ctx.has_position and ctx.close < ma20:
        return sell("all")
    return None
